"""DPAPI blob parsing and decryption.

A DPAPI blob names the master-key GUID that protects it, a cipher and hash algorithm,
a salt, an HMAC and the ciphertext. Decryption derives a session key from the master
key and the salt (plus optional entropy), expands it with CryptDeriveKey, decrypts in
CBC, then verifies the HMAC before returning the cleartext.
"""
import struct

from . import primitives as P

# The DPAPI provider GUID, little-endian, as it appears on disk. Credential and Vault
# containers wrap a blob that begins four bytes (the version field) before this.
PROVIDER_GUID_LE = bytes.fromhex('d08c9ddf0115d1118c7a00c04fc297eb')


def _u32(buf, off):
    return struct.unpack('<L', buf[off:off + 4])[0]


class DpapiBlob:
    """A parsed DPAPI blob."""

    def __init__(self, raw):
        self.raw = raw
        o = 4                                   # version
        self.provider = raw[o:o + 16]
        o += 16
        signed_start = o                         # HMAC covers from here (mk version on)
        self.mk_version = _u32(raw, o)
        o += 4
        self.mk_guid = self._guid(raw[o:o + 16])
        o += 16
        self.flags = _u32(raw, o)
        o += 4
        desc_len = _u32(raw, o)
        o += 4
        self.description = raw[o:o + desc_len].decode('utf-16-le', 'replace').strip('\x00')
        o += desc_len
        self.alg_crypt = _u32(raw, o)
        o += 8                                   # CryptAlgo + key length (bits)
        salt_len = _u32(raw, o)
        o += 4
        self.salt = raw[o:o + salt_len]
        o += salt_len
        strong_len = _u32(raw, o)
        o += 4 + strong_len                      # "strong password" region, unused here
        self.alg_hash = _u32(raw, o)
        o += 8                                   # HashAlgo + hash length (bits)
        hmac_len = _u32(raw, o)
        o += 4
        self.hmac = raw[o:o + hmac_len]
        o += hmac_len
        data_len = _u32(raw, o)
        o += 4
        self.cipher_text = raw[o:o + data_len]
        o += data_len
        self.signed = raw[signed_start:o]
        sign_len = _u32(raw, o)
        self.sign = raw[o + 4:o + 4 + sign_len]
        self.end = o + 4 + sign_len

    @staticmethod
    def _guid(b):
        d1, d2, d3 = struct.unpack('<LHH', b[:8])
        return '%08x-%04x-%04x-%s-%s' % (d1, d2, d3, b[8:10].hex(), b[10:16].hex())

    def decrypt(self, master_key, entropy=None):
        """The cleartext, or ``None`` if the HMAC does not verify for any session type."""
        key_len, iv_len = P.cipher_sizes(self.alg_crypt)
        for algo in P.SESSION_KEY_ALGOS:
            session = algo(master_key, self.salt, self.alg_hash, entropy=entropy)
            derived = P.crypt_derive_key(session, self.alg_hash, key_len + iv_len)
            clear = P.cbc_decrypt(self.alg_crypt, derived[:key_len], b'\x00' * iv_len,
                                  self.cipher_text)
            verify = algo(master_key, self.hmac, self.alg_hash, entropy=entropy,
                          extra=self.signed)
            if verify == self.sign:
                pad = clear[-1] if clear else 0
                if 0 < pad <= iv_len:
                    clear = clear[:-pad]
                return clear
        return None


def decrypt_blob(raw, master_key, entropy=None):
    """Convenience: parse ``raw`` and decrypt it with ``master_key``."""
    return DpapiBlob(raw).decrypt(master_key, entropy=entropy)


def find_blob_offset(data):
    """The offset of the DPAPI blob inside a container, located by the provider GUID.

    The blob's version field sits four bytes before the provider GUID, so the blob
    begins at ``guid_offset - 4``. Returns ``None`` if no provider GUID is present.
    """
    pos = data.find(PROVIDER_GUID_LE)
    if pos < 4:
        return None
    return pos - 4
